// CMDB Core Relational Data Model & Seed Store
// Re-architected strictly around Projects (按项目分资产)
// Sourced from 《信息资产台账-v331toAI.xlsx》

export interface ProjectGroup {
  id: string;
  name: string;
  code: string;
  customerName: string;
  env: string;
  cloudVendor: string;
  regionName: string;
  deviceCount: number;
  phyCount: number;
  vmCount: number;
  netCount: number;
  totalCores: number;
  totalMemoryGb: number;
  totalDiskGb: number;
  xinchuangCount: number;
  description: string;
  healthScore: number;
}

// Standardized Asset Interface encompassing ALL Excel Fields
export interface AssetMeta {
  seq?: number;
  customerName?: string | null;
  projectName?: string | null;
  projectId?: string | null;
  env?: string | null;
  cloudVendor?: string | null;
  regionName?: string | null;
  category?: string | null;
  deviceType?: string | null;
  privateIp?: string | null;
  privateIpv6?: string | null;
  internalWanIp?: string | null;
  eip?: string | null;
  vip?: string | null;
  publicIp?: string | null;
  cpuArch?: string | null;
  cpuCores?: number | null;
  memoryGb?: number | null;
  systemDiskGb?: number | null;
  dataDiskGb?: number | null;
  sharedDiskGb?: number | null;
  objectStorageGb?: number | null;
  osFamily?: string | null;
  osVersion?: string | null;
  kernelVersion?: string | null;
  isXinchuang?: string | null;
  remotePort?: number | null;
  remarks?: string | null;
}

export interface PhysicalHost extends AssetMeta {
  id: string;
  assetNo: string;
  hostname: string;
  name: string;
  ip: string;
  bmcIp: string;
  brand: string;
  model: string;
  os: string;
  cpu: string;
  memory: string;
  disk: string;
  role: string;
  businessId: string;
  status: "running" | "warning" | "offline";
  powerWatts: number;
  cpuTemp: number;
  boardTemp: number;
  inletTemp: number;
  fanRpm: string;
  psu1Status: string;
  psu2Status: string;
  raidStatus: string;
  agentOnline: boolean;
  updated: string;
}

export interface VmHost extends AssetMeta {
  id: string;
  name: string;
  physicalHostId: string;
  ip: string;
  privateIp: string;
  cpu: string;
  memory: string;
  disk: string;
  os: string;
  businessId: string;
  status: "running" | "stopped";
  role: string;
  updated: string;
}

export interface SwitchDevice extends AssetMeta {
  id: string;
  assetNo: string;
  name: string;
  ip: string;
  brand: string;
  model: string;
  role: string;
  portCount: number;
  activePorts: number;
  status: "online" | "warning" | "offline";
  businessId: string;
}

export interface DatabaseAsset {
  id: string;
  name: string;
  type: "MySQL" | "Redis" | "PostgreSQL" | "MongoDB" | "Oracle";
  version: string;
  hostIp: string;
  port: number;
  arch: string;
  businessId: string;
  projectName?: string;
  dataSize: string;
  connectionCount: number;
  status: "active" | "standby" | "maintenance";
}

export interface BusinessModel {
  id: string;
  name: string;
  code: string;
  level: "核心 L1" | "重要 L2" | "通用 L3";
  owner: string;
  department: string;
  description: string;
  healthScore: number;
  hostIds: string[];
  dbIds: string[];
  switchIds: string[];
}

export interface AgentProbe {
  id: string;
  hostIp: string;
  hostname: string;
  agentVersion: string;
  status: "online" | "offline";
  cpuUsage: number;
  memUsage: number;
  lastHeartbeat: string;
}

export interface CredentialItem {
  id: string;
  name: string;
  type: "SSH 密码" | "SSH 私钥" | "BMC IPMI" | "SNMP v2c/v3" | "数据库账号";
  username: string;
  targetCount: number;
  updated: string;
  remark: string;
}

